    d = distance_to(enemy.x, enemy.y)

    radial = sqrt(me.x * me.x + me.y * me.y)
    if radial > 5.8:
        b = bearing_to(0.0, 0.0)

    if abs(b) > 30:
        turn = 0.8
        if b > 0:
            return (-turn, turn)
        return (turn, -turn)

    base = 1.0 if d > 1.8 else 0.85
    correction = max(-1.0, min(1.0, b / 25.0))
    left = base - 0.55 * correction
    right = base + 0.55 * correction
    return (max(-1.0, min(1.0, left)),
            max(-1.0, min(1.0, right)))


def weapons(me, enemy, arena):
    front = me.weapons.get("front")
    back = me.weapons.get("back")

    if me.inverted:
        if me.righting:
            return []
        if not me.memory.get("right_attempt"):
            if (back and back.get("health", 0) > 0 and
                    back.get("ready", False) and
                    back.get("shots_left", 0) > 0 and
                    me.battery_wh > 0 and me.battery_health > 0):
                me.memory["right_attempt"] = 1
                return [self_right()]
        if front and front.get("health", 0) > 0 and me.battery_wh > 0:
            return [spin("front", 2100)]
        return []

    if me.memory.get("right_attempt"):
        me.memory.pop("right_attempt", None)

    if me.on_side:
        if me.righting:
            return []
        last = me.memory.get("side_try", -10.0)
        if arena.time - last >= 1.0:
            me.memory["side_try"] = arena.time
            return [self_right()]
        return []

    commands = []
    if front and front.get("health", 0) > 0 and me.battery_wh > 0:
        commands.append(spin("front", 2100))

    if (back and back.get("health", 0) > 0 and
            back.get("ready", False) and
            back.get("shots_left", 0) > 0):
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        if (abs(b) > 115 and d < 0.95 and
                not enemy.airborne and not enemy.held and not enemy.lifted):
            commands.append(flip("back"))

    return commands

