def drive(me, enemy, arena):
    if not me.can_drive or me.battery_wh <= 0:
        return (0, 0)

    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)
    vulnerable = enemy.on_side or enemy.inverted

    my_radius = sqrt(me.x * me.x + me.y * me.y)
    enemy_radius = sqrt(enemy.x * enemy.x + enemy.y * enemy.y)
    if my_radius > 5.55 and enemy_radius < my_radius - 0.3:
        b = bearing_to(0, 0)

    if d < 1.55 and not vulnerable:
        a = radians(enemy.heading)
        offset = enemy.width * 0.5 + 0.14
        target_x = enemy.x + sin(a) * offset
        target_y = enemy.y - cos(a) * offset
        b = bearing_to(target_x, target_y)

    if abs(b) > 115:
        if b > 0:
            return (0.1, 1.0)
        return (1.0, 0.1)

    base = 1.0
    if d < 1.15:
        base = 0.6
    elif d < 1.65:
        base = 0.82

    if abs(b) > 18:
        correction = b / 115.0
        left = base - 1.1 * correction
        right = base + 1.1 * correction
    else:
        left = base
        right = base

    return (max(-1.0, min(1.0, left)),
            max(-1.0, min(1.0, right)))


